generetiOperatorText.guide:
{
  "format": "genereti-guide",
  "version": 1,
  "id": "my-first-texture-lesson",
  "title": "My first texture lesson",
  "summary": "A short lesson with hints, recorded typing and playback you can customize.",
  "steps": [
    {
      "title": "Make a different pattern",
      "text": "Change x*8 to x*4 and watch the image.",
      "target": {
        "nodeType": "GeneretiTextureExpression",
        "part": "code",
        "widget": "expression"
      },
      "check": {
        "kind": "changed-widget"
      },
      "hint": "Edit the expression yourself, or use Do it to watch an example appear.",
      "actions": [
        {
          "kind": "pointer",
          "target": {
            "nodeType": "GeneretiTextureExpression",
            "nodeId": 2,
            "part": "code"
          },
          "gesture": "click",
          "from": [
            0.5,
            0.4
          ]
        },
        {
          "kind": "type-text",
          "target": {
            "nodeType": "GeneretiTextureExpression",
            "nodeId": 2,
            "part": "code",
            "widget": "expression"
          },
          "value": "(sin(x * 12 + t) + cos(y * 12 - t)) / 2"
        }
      ]
    },
    {
      "title": "Present your texture",
      "text": "Select the image preview and press Alt+W to open its overlay. Hover outside an edge to reveal the controls.",
      "target": {
        "nodeType": "GeneretiLiveImagePreview",
        "part": "toolbar"
      },
      "check": {
        "kind": "overlay-open"
      }
    },
    {
      "title": "Type a teaching note",
      "text": "Do it types into a real DAT field. Try writing your own note afterward.",
      "hint": "The dat.text editor stores ordinary workflow text.",
      "target": {
        "nodeType": "GeneretiDatText",
        "nodeId": 4,
        "part": "code",
        "widget": "text"
      },
      "actions": [
        {
          "kind": "type-text",
          "target": {
            "nodeType": "GeneretiDatText",
            "nodeId": 4,
            "part": "code",
            "widget": "text"
          },
          "value": "# A recorded lesson\n\nSelections focus tools. Actions demonstrate changes.\n\nTry it yourself, ask for a hint, or use Do it."
        }
      ]
    }
  ]
}

